/**
 * Page Object for Login / Password Reset
 * Source: cypress/e2e/orangehrm-login.cy.js, orangehrm-password-reset.cy.js
 * Generated by: /tw-e2e-page-object
 *
 * Selector strategy (third-party app — data-testid cannot be added):
 *   1. input[name] / button[type]  — stable HTML attributes
 *   2. [role="alert"]              — ARIA (stable)
 *   3. cy.contains('tag', 'text')  — text-based (moderate)
 *   4. [class*="branding"]         — partial class match (moderate)
 *   TODO: If OrangeHRM ever exposes data-testid, replace fallbacks above.
 */
class LoginPage {

    // --- Stable HTML attribute selectors ---
    usernameInput = 'input[name="username"]';
    passwordInput = 'input[name="password"]';
    loginButton   = 'button[type="submit"]';

    // --- Navigation ---

    visit() {
        cy.visit('/auth/login');
        return this;
    }

    // --- Actions ---

    typeUsername(username) {
        cy.get(this.usernameInput).type(username);
        return this;
    }

    typePassword(password) {
        cy.get(this.passwordInput).type(password);
        return this;
    }

    clickLogin() {
        cy.get(this.loginButton).click();
        return this;
    }

    clickForgotPassword() {
        // OrangeHRM renders this as a <p> not <a> — omit tag to match any element
        cy.contains('Forgot your password?').click();
        return this;
    }

    login(username, password) {
        this.typeUsername(username);
        this.typePassword(password);
        this.clickLogin();
        return this;
    }

    submitResetPasswordRequest(username) {
        cy.get(this.usernameInput).clear().type(username);
        cy.contains('button', 'Reset Password').click();
        return this;
    }

    // --- Assertions ---

    verifyLogoIsVisible() {
        // [class*="branding"] is a partial match — survives minor class renames
        cy.get('[class*="branding"] img').should('be.visible').and('have.attr', 'src');
        return this;
    }

    verifyLoginTitle(title = 'Login') {
        cy.contains('h5', title).should('be.visible');
        return this;
    }

    verifyFormElementsAreVisible() {
        cy.get(this.usernameInput).should('be.visible');
        cy.get(this.passwordInput).should('be.visible');
        cy.get(this.loginButton).should('be.visible');
        return this;
    }

    verifyErrorMessage(message = 'Invalid credentials') {
        // [role="alert"] is ARIA-stable — preferred over .oxd-alert-content
        cy.get('[role="alert"]').should('be.visible').and('contain', message);
        return this;
    }

    verifyValidationErrors(count = 2) {
        // .oxd-input-field-error-message is the most specific selector available
        // on this third-party app for field-level validation messages
        cy.get('.oxd-input-field-error-message').should('have.length', count);
        cy.get('.oxd-input-field-error-message').first().should('contain', 'Required');
        return this;
    }

    verifySuccessfulLogin() {
        cy.url().should('include', '/dashboard/index');
        cy.contains('h6', 'Dashboard').should('be.visible');
        return this;
    }

    verifyForgotPasswordPage() {
        cy.url().should('include', '/auth/requestPasswordResetCode');
        cy.contains('h6', 'Reset Password').should('be.visible');
        cy.contains('p', 'Please').should('be.visible');
        return this;
    }

    verifyResetPasswordConfirmation() {
        // OrangeHRM navigates to /auth/requestResetPassword after form submission
        cy.url().should('include', '/auth/requestResetPassword');
        return this;
    }

    verifyUsernameRequiredError() {
        cy.get('.oxd-input-field-error-message').should('be.visible').and('contain', 'Required');
        return this;
    }
}

export default new LoginPage();
